args.content:
SELECT ?item ?itemLabel ?coord
WHERE {
  ?item wdt:P31/wdt:P279* wd:Q15474482 ;  # point of interest
        wdt:P625 ?coord .
  FILTER (
    ?item/wdt:P361 ?parentItem .
    ?parentItem/wdt:P361 ?grandparentItem .
    ?grandparentItem/wdt:P361 ?topLevelItem .
    ?topLevelItem wdt:P31 wd:Q6256 ;  # inhabited place
                  wdt:P17 wd:Q29  # Spain
  )
  FILTER (
    ?item/wdt:P361 ?cityItem .
    ?cityItem wdt:P361 ?regionItem .
    ?regionItem wdt:P361 ?countryItem .
    ?countryItem wdt:P31 wd:Q29  # Spain
  )
  OPTIONAL {
    ?item skos:label ?itemLabel
  }
  OPTIONAL {
    ?coord wdt:P625 ?coord
  }
  FILTER (
    ?itemLabel != "" || ?itemLabel != "" 
  )
}
LIMIT 100

